  1	/**
  2	 * Tests for WP-010: GUI Credential-Missing Error Display.
  3	 *
  4	 * Acceptance Criteria verified:
  5	 *   AC1 — When a repository's clone error contains the credential-missing
  6	 *          sentinel text ("requires a credential for host"), the workspace
  7	 *          detail view shows a "Missing Credential" badge instead of the
  8	 *          generic "No data" badge.
  9	 *   AC2 — The "Missing Credential" badge links to the repository detail view
 10	 *          (#/repositories/:id) where the user can select a credential.
 11	 *   AC3 — Non-credential clone errors continue to display as the generic
 12	 *          "No data" badge (no regression in existing error display).
 13	 *   AC4 — The credential-missing error detection uses the sentinel text
 14	 *          ("requires a credential for host") from the orchestrator error
 15	 *          messages (WP-007).
 16	 *
 17	 * Additional toast message tests:
 18	 *   T1  — When all failures are credential-related, the toast mentions
 19	 *          "credential errors" and the affected repository IDs.
 20	 *   T2  — When failures are a mix of credential and non-credential, the
 21	 *          toast distinguishes them with two segments:
 22	 *          "Missing credentials for: <cred-repos>. Failed to clone: <other-repos>."
 23	 *   T3  — When all failures are non-credential, the original toast message
 24	 *          is shown unchanged.
 25	 *
 26	 * Uses Node's built-in test runner with jsdom for a minimal DOM environment.
 27	 * Run individually with:
 28	 *   node --test gui/public/js/views/workspace-detail.credential-error.test.mjs
 29	 */
 30	
 31	import { test, beforeEach } from 'node:test';
 32	import assert from 'node:assert/strict';
 33	import { JSDOM } from 'jsdom';
 34	
 35	// ---------------------------------------------------------------------------
 36	// jsdom setup — install globals before any module is loaded
 37	// ---------------------------------------------------------------------------
 38	
 39	const dom = new JSDOM(
 40	    '<!DOCTYPE html><html><body><div id="toast-container"></div><div id="app"></div></body></html>',
 41	    { url: 'http://localhost/' },
 42	);
 43	
 44	const { window } = dom;
 45	
 46	globalThis.document    = window.document;
 47	globalThis.window      = window;
 48	globalThis.location    = window.location;
 49	globalThis.HTMLElement = window.HTMLElement;
 50	globalThis.CSS = window.CSS ?? { escape: (s) => s.replace(/["\\]/g, '\\$&') };
 51	
 52	// Stub setInterval / clearInterval so the polling loop never fires and the
 53	// process exits cleanly after tests complete.
 54	let _intervalId = 0;
 55	const _intervals = new Map();
 56	globalThis.setInterval = (fn, delay) => {
 57	    const id = ++_intervalId;
 58	    _intervals.set(id, { fn, delay });
 59	    return id;
 60	};
 61	globalThis.clearInterval = (id) => {
 62	    _intervals.delete(id);
 63	};
 64	
 65	// ---------------------------------------------------------------------------
 66	// Minimal fetch mock (required by api.js)
 67	// ---------------------------------------------------------------------------
 68	
 69	globalThis.fetch = async () => ({
 70	    status: 200,
 71	    ok: true,
 72	    statusText: 'OK',
 73	    headers: { get: () => 'application/json' },
 74	    json: async () => ({}),
 75	});
 76	
 77	// ---------------------------------------------------------------------------
 78	// Import dependencies and patch api
 79	// ---------------------------------------------------------------------------
 80	
 81	const { api } = await import('../api.js');
 82	
 83	// Credential-missing sentinel — must match CREDENTIAL_MISSING_SENTINEL in
 84	// workspace-detail.js and the error message template in the orchestrators.
 85	const SENTINEL = 'requires a credential for host';
 86	
 87	// Setup spy — controls what the API returns after workspace setup.
 88	const setupCalls = [];
 89	let setupResult  = { results: [] };
 90	api.workspaces.setup = async (projectId, wid) => {
 91	    setupCalls.push({ projectId, wid });
 92	    return setupResult;
 93	};
 94	
 95	// Default stubs for the remaining api calls used by renderWorkspaceDetail.
 96	api.workspaces.get    = async () => ({
 97	    Id: 'DEV', id: 'DEV', Description: '', initialized: false, folderPath: '/tmp/dev',
 98	});
 99	api.workspaces.health = async () => ({ healthy: true, issues: [] });
100	api.workspaces.launch = api.workspaces.launch || {};

101	api.workspaces.launch.githubDesktop = async () => ({ success: true });
102	api.workspaces.launch.vscode        = async () => ({ success: true });
103	api.projects.get      = async () => ({
104	    Id: 'my-project',
105	    Repositories: ['repo-alpha', 'repo-beta'],
106	});
107	
108	// Status refresh: by default, no repos have status data yet.
109	let statusMapOverride = {};
110	api.status.refresh = async () => statusMapOverride;
111	api.status.get     = async () => statusMapOverride;
112	
113	if (!api.config)          api.config          = {};
114	if (!api.config.polling)  api.config.polling  = {};
115	api.config.polling.get = async () => ({ gitPollingIntervalSeconds: 60 });
116	if (!api.config.webserverUrl) api.config.webserverUrl = {};
117	api.config.webserverUrl.get = async () => ({ webserverUrl: '' });
118	
119	const { renderWorkspaceDetail } = await import('./workspace-detail.js');
120	
121	// Local re-declaration — see gui/public/js/utils/dom.js for the canonical export.
122	// Static imports from ../utils/dom.js cannot be resolved in this Node.js jsdom harness.
123	function clearElement(el) { while (el.firstChild) el.removeChild(el.firstChild); }
124	
125	// ---------------------------------------------------------------------------
126	// Render helper
127	// ---------------------------------------------------------------------------
128	
129	/**
130	 * Render the workspace-detail view and wait for the async bootstrap to settle.
131	 *
132	 * We poll until a `<table>` or `.workspace-detail-header` element appears, or
133	 * a maximum tick budget is exhausted.
134	 *
135	 * @param {string} [projectId]
136	 * @param {string} [wid]
137	 * @returns {Promise<{ container: HTMLElement, cleanup: function }>}
138	 */
139	async function renderView(projectId = 'my-project', wid = 'DEV') {
140	    const container = window.document.getElementById('app');
141	    clearElement(container);
142	
143	    const cleanup = renderWorkspaceDetail(container, { id: projectId, wid });
144	
145	    await new Promise((resolve) => {
146	        let ticks = 0;
147	        const poll = () => {
148	            ticks++;
149	            if (
150	                container.querySelector('table') ||
151	                container.querySelector('.workspace-detail-header') ||
152	                ticks > 200
153	            ) {
154	                resolve();
155	            } else {
156	                Promise.resolve().then(poll);
157	            }
158	        };
159	        Promise.resolve().then(poll);
160	    });
161	
162	    return { container, cleanup };
163	}
164	
165	/**
166	 * Simulate a setup button click and wait for the DOM to update.
167	 *
168	 * @param {HTMLElement} container
169	 */
170	async function clickSetupAndWait(container) {
171	    const setupBtn = [...container.querySelectorAll('button')]
172	        .find((b) => b.textContent.includes('Setup Workspace'));
173	    assert.ok(setupBtn, 'Setup Workspace button must be present to simulate setup');
174	
175	    setupBtn.click();
176	
177	    // Drain microtask queue — the click handler is async, so we need several
178	    // ticks for the await chain inside the click handler to settle.
179	    for (let i = 0; i < 20; i++) {
180	        await new Promise((r) => Promise.resolve().then(r));
181	    }
182	}
183	
184	// ---------------------------------------------------------------------------
185	// Per-test reset
186	// ---------------------------------------------------------------------------
187	
188	beforeEach(() => {
189	    setupCalls.length   = 0;
190	    setupResult         = { results: [] };
191	    statusMapOverride   = {};
192	    _intervals.clear();
193	    clearElement(document.getElementById('toast-container'));
194	    // Restore default: workspace NOT initialized so the Setup button is present.
195	    api.workspaces.get = async () => ({
196	        Id: 'DEV', id: 'DEV', Description: '', initialized: false, folderPath: '/tmp/dev',
197	    });
198	});
199	
200	// ---------------------------------------------------------------------------
201	// AC1 — "Missing Credential" badge shown when credential error detected
202	// ---------------------------------------------------------------------------
203	
204	test('AC1: setup result with credential-missing sentinel shows "Missing Credential" badge for that repo', async () => {
205	    // repo-alpha fails with the credential sentinel; repo-beta succeeds.
206	    setupResult = {
207	        results: [
208	            { repositoryId: 'repo-alpha', success: false, error: `Repository 'repo-alpha' ${SENTINEL} 'github.com'. Please select a credential in the repository settings.` },
209	            { repositoryId: 'repo-beta',  success: true },
210	        ],
211	    };
212	
213	    const { container, cleanup } = await renderView();
214	    try {
215	        await clickSetupAndWait(container);
216	
217	        const tbody = container.querySelector('tbody');
218	        assert.ok(tbody, 'status table tbody should exist');
219	
220	        // repo-alpha row should have the credential badge.
221	        const alphaRow = tbody.querySelector('tr[data-repo-id="repo-alpha"]');
222	        assert.ok(alphaRow, 'repo-alpha row should be present');
223	
224	        const badgeWrapper = alphaRow.querySelector('div[data-repo-id="repo-alpha"]');
225	        assert.ok(badgeWrapper, 'badge wrapper should be present');
226	
227	        const credBadge = badgeWrapper.querySelector('.status-badge-credential');
228	        assert.ok(credBadge, 'Missing Credential badge (.status-badge-credential) should be present for repo-alpha');
229	        assert.ok(
230	            credBadge.textContent.includes('Missing Credential'),
231	            `badge text should contain "Missing Credential", got: "${credBadge.textContent}"`,
232	        );
233	    } finally {
234	        cleanup();
235	    }
236	});
237	
238	test('AC1: repo with non-credential clone error retains generic "No data" badge', async () => {
239	    // repo-alpha fails with a generic error (not the sentinel).
240	    setupResult = {
241	        results: [
242	            { repositoryId: 'repo-alpha', success: false, error: 'fatal: repository not found' },
243	        ],
244	    };
245	
246	    const { container, cleanup } = await renderView();
247	    try {
248	        await clickSetupAndWait(container);
249	
250	        const tbody = container.querySelector('tbody');
251	        assert.ok(tbody, 'status table tbody should exist');
252	
253	        const alphaRow = tbody.querySelector('tr[data-repo-id="repo-alpha"]');
254	        assert.ok(alphaRow, 'repo-alpha row should be present');
255	
256	        const badgeWrapper = alphaRow.querySelector('div[data-repo-id="repo-alpha"]');
257	        assert.ok(badgeWrapper, 'badge wrapper should be present');
258	
259	        // Must NOT have the credential badge.
260	        const credBadge = badgeWrapper.querySelector('.status-badge-credential');
261	        assert.strictEqual(credBadge, null, 'credential badge must NOT be shown for non-credential errors');
262	
263	        // Should still have the generic error badge.
264	        const errorBadge = badgeWrapper.querySelector('.status-badge-error');
265	        assert.ok(errorBadge, 'generic error badge (.status-badge-error) should remain for non-credential errors');
266	    } finally {
267	        cleanup();
268	    }
269	});
270	
271	// ---------------------------------------------------------------------------
272	// AC2 — badge links to #/repositories/:id
273	// ---------------------------------------------------------------------------
274	
275	test('AC2: "Missing Credential" badge href points to #/repositories/:repoId', async () => {
276	    setupResult = {
277	        results: [
278	            { repositoryId: 'repo-alpha', success: false, error: `repo-alpha ${SENTINEL} 'example.com'` },
279	        ],
280	    };
281	
282	    const { container, cleanup } = await renderView();
283	    try {
284	        await clickSetupAndWait(container);
285	
286	        const badgeWrapper = container.querySelector('div[data-repo-id="repo-alpha"]');
287	        assert.ok(badgeWrapper, 'badge wrapper should be present');
288	
289	        const credBadge = badgeWrapper.querySelector('.status-badge-credential');
290	        assert.ok(credBadge, 'credential badge should be present');
291	
292	        const href = credBadge.getAttribute('href');
293	        assert.ok(
294	            href && href.includes('#/repositories/repo-alpha'),
295	            `href should point to #/repositories/repo-alpha, got: "${href}"`,
296	        );
297	    } finally {
298	        cleanup();
299	    }
300	});

101	export function setRouter(router) {
102	    _router = router;
103	}
104	
105	// ---------------------------------------------------------------------------
106	// Constants
107	// ---------------------------------------------------------------------------
108	
109	/** Default polling interval in milliseconds (fallback when config fetch fails). */
110	const DEFAULT_POLL_INTERVAL_MS = 10_000;
111	
112	// ---------------------------------------------------------------------------
113	// Normalisation helpers — imported from utils/normalise.js
114	// extractRepoId and extractRepoName remain local (workspace-detail only).
115	// ---------------------------------------------------------------------------
116	
117	/**
118	 * Extract a repository's ID from either a plain string or an object.
119	 * The backend may return Repositories as an array of strings, an array of
120	 * objects with `Id`/`id`, or an array of objects with `repositoryId`.
121	 *
122	 * @param {string|Object} repo
123	 * @returns {string}
124	 */
125	function extractRepoId(repo) {
126	    if (typeof repo === 'string') return repo;
127	    return repo.Id || repo.id || repo.RepositoryId || repo.repositoryId || '';
128	}
129	
130	/**
131	 * Extract a human-readable repository name from a repository entry.
132	 * Falls back to the ID when no name is available.
133	 *
134	 * @param {string|Object} repo
135	 * @returns {string}
136	 */
137	function extractRepoName(repo) {
138	    if (typeof repo === 'string') return repo;
139	    return repo.Name || repo.name || extractRepoId(repo);
140	}
141	
142	// ---------------------------------------------------------------------------
143	// Loading helper
144	// ---------------------------------------------------------------------------
145	
146	/**
147	 * Render a loading spinner into `el`.
148	 *
149	 * @param {HTMLElement} el
150	 * @param {string} [label]
151	 */
152	function showLoading(el, label = 'Loading…') {
153	    clearElement(el);
154	    const wrapper = document.createElement('div');
155	    wrapper.className = 'loading-indicator';
156	    wrapper.setAttribute('aria-live', 'polite');
157	
158	    const spinner = document.createElement('span');
159	    spinner.className = 'spinner';
160	    spinner.setAttribute('aria-hidden', 'true');
161	    wrapper.appendChild(spinner);
162	
163	    const labelEl = document.createElement('span');
